-- `BY DEFAULT` takes the same refusal as `ALWAYS` over a column not declared `NOT NULL`.
-- @expect-error: the column is not declared NOT NULL
-- @expect-message
-- @setup
CREATE TABLE ai (c BIGINT, v TEXT);
INSERT INTO ai VALUES (1, 'one');
-- @test
ALTER TABLE ai ALTER COLUMN c ADD GENERATED BY DEFAULT AS IDENTITY (START WITH 10);
